using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// Configure the AI client
var openAiClient = new OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key");

IChatClient chatClient = openAiClient
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Set up tools
var notepad = new Notepad();
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchWeb),
        AIFunctionFactory.Create(notepad.AddNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]
};

// Agent system prompt
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. When given a topic:
        1. Search the web for relevant information (perform multiple searches if needed)
        2. Take notes on key findings using the note-taking tool
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary

        Always search for multiple aspects of the topic to ensure thorough coverage.
        """)
};

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
messages.Add(new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"));

// Run the agent loop
var response = await chatClient.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// --- Tool Definitions ---

/// <summary>Simulates web search results for demonstration purposes.</summary>
static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  [Searching web for: \"{query}\"]");

        // In production, integrate a real search API (Bing, Google, etc.)
        return $"""
            Search results for "{query}":
            1. Wikipedia summary: {query} is a widely discussed topic with multiple perspectives
               and ongoing developments in the field.
            2. Recent news: Latest developments in {query} show significant progress
               in 2026, with new breakthroughs reported by researchers.
            3. Academic source: Studies indicate that {query} has broad implications
               for technology, society, and future innovation.
            4. Industry report: Market analysis suggests growing interest and investment
               in {query}-related technologies and applications.
            """;
    }
}

/// <summary>Note-taking tool that allows the agent to record and retrieve findings.</summary>
class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Adds a note to the research notepad for later reference.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note added: {note[..Math.Min(note.Length, 60)]}...]");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far during research.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  [Retrieving {_notes.Count} notes]");
        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

